def adaptar_ventas_existentes(apps, schema_editor):
    """El medio de pago pasa de texto libre ("Webpay - Débito") a un código, y la
    anulación, que solo estaba en el envío, queda también en la venta."""
    Venta = apps.get_model('appPrincipal', 'Venta')
    Venta.objects.filter(metodo_pago__istartswith='webpay').update(metodo_pago='webpay')
    Venta.objects.exclude(metodo_pago='webpay').update(metodo_pago='')
    Venta.objects.filter(datos_envio__estado='Anulada', anulada_en__isnull=True).update(
        anulada_en=django.utils.timezone.now()
    )


